INSERT INTO reviews (title, author, genre, rating, review, reviewer) VALUES
('The Left Hand of Darkness', 'Ursula K. Le Guin', 'Science Fiction', 5,
INSERT INTO reviews (title, author, genre, rating, review, reviewer, created_at, updated_at) VALUES
('Dune', 'Frank Herbert', 'Science Fiction', 4, 'Sprawling and strange, but the sandworms and the Fremen training scenes are worth the slog. Paul''s whole arc feels inevitable in the best and most uncomfortable way. The first hundred pages are rough going though.', 'Sam', now() - interval '412 days', now() - interval '412 days'),
('Neuromancer', 'William Gibson', 'Science Fiction', 3, 'Case jacking into the matrix from a grubby Chiba City hotel is still wonderfully cool. The prose is dense and the plot barely holds together, but the vibe carries it. Molly''s mirror shades alone are iconic.', 'Priya', now() - interval '37 days', now() - interval '37 days'),
('The Dispossessed', 'Ursula K. Le Guin', 'Science Fiction', 5, 'Anarres versus Urras, told through Shevek''s back-and-forth, is one of the smartest books I''ve read about utopia. Le Guin doesn''t let either society off the hook. It took a few chapters to get into the time structure, but it pays off.', 'Alex', now() - interval '298 days', now() - interval '294 days'),
('The Martian', 'Andy Weir', 'Science Fiction', 4, 'Mark Watney''s wisecracking voice makes a book about potatoes and duct tape extremely readable. The science is fussy in a satisfying way. The middle act drags a little when the NASA politics kick in.', 'Jordan', now() - interval '151 days', now() - interval '151 days'),
('A Wizard of Earthsea', 'Ursula K. Le Guin', 'Fantasy', 4, 'Ged and the shadow he lets loose make a perfect short fantasy. The islands feel real, and the magic is quiet and grounded in the true names of things. I read it as a teenager and it still holds up.', 'Mei', now() - interval '503 days', now() - interval '503 days'),
('Jonathan Strange & Mr Norrell', 'Susanna Clarke', 'Fantasy', 2, 'Clarke''s footnotes are clever, but the book is far too long for what it is. Mr Norrell''s fussy fairy magic drags on, and I lost patience with the Napoleonic war subplot. Stick with it for the fairy king scenes.', 'Sam', now() - interval '66 days', now() - interval '66 days'),
('The Name of the Wind', 'Patrick Rothfuss', 'Fantasy', 5, 'Kvothe telling his own story in an inn is a great hook, and the magic-as-academic-study angle at the University is fun. Rothfuss writes gorgeous sentences. The series is still waiting on a third book, which is hard to forgive.', 'Priya', now() - interval '224 days', now() - interval '224 days'),
('The Hobbit', 'J.R.R. Tolkien', 'Fantasy', 5, 'Bilbo''s riddle game with Gollum is still the best scene in any fantasy book. Cosy, funny, and a perfect first trip to Middle-earth. The songs at Bag End feel a bit like padding, but nobody minds.', NULL, now() - interval '118 days', now() - interval '118 days'),
('Never Let Me Go', 'Kazuo Ishiguro', 'Literary Fiction', 4, 'The quiet horror of Hailsham and the carers, delivered in Kathy''s calm, polite voice, is devastating. Ishiguro never raises his voice once. I finished it on a train and had to sit still for a while.', 'Alex', now() - interval '357 days', now() - interval '357 days'),
('The Remains of the Day', 'Kazuo Ishiguro', 'Literary Fiction', 5, 'Stevens and his butler''s dignity, while the England outside falls apart, is so precise it hurts. The ending is perfect. Be warned that you''ll want to shake him for about two hundred pages.', 'Tomás', now() - interval '29 days', now() - interval '29 days'),
('Beloved', 'Toni Morrison', 'Literary Fiction', 4, 'Sethe''s house at 124 Bluestone Road is haunted in every sense, and Morrison makes the ghost feel like grief made physical. The fragmented sections are hard going at first. It''s not an easy read, but it''s an essential one.', 'Ruth', now() - interval '442 days', now() - interval '442 days'),
('Middlesex', 'Jeffrey Eugenides', 'Literary Fiction', 3, 'Cal''s story, from a Greek village to 1960s Detroit, is funny and sprawling. The family history is the best part. The second half loses some momentum, but I didn''t mind.', 'Sam', now() - interval '185 days', now() - interval '182 days'),
('Wolf Hall', 'Hilary Mantel', 'Historical Fiction', 2, 'Cromwell as the guy who actually gets things done is a clever flip, but the present tense got on my nerves within fifty pages. Too much court politics and not enough Anne Boleyn. Respectable, but I didn''t love it.', 'Jordan', now() - interval '88 days', now() - interval '88 days'),
('The Book Thief', 'Markus Zusak', 'Historical Fiction', 4, 'Death narrating a story about Liesel and her stolen books in Molching is a bold choice that mostly works. Rudy is a wonderful character. The ending got me in a way I didn''t expect.', 'Priya', now() - interval '262 days', now() - interval '262 days'),
('Pachinko', 'Min Jin Lee', 'Historical Fiction', 5, 'Four generations of a Korean family in Osaka, with Sunja at the centre, feels like a novel that knows exactly how much history to fit in each chapter. The prejudice Sunja faces is quietly brutal. Min Jin Lee''s sentences are simple and sharp.', 'Mei', now() - interval '15 days', now() - interval '15 days'),
('Wild Swans', 'Jung Chang', 'Non-fiction', 3, 'Three generations of women in Sichuan, from Jung Chang''s grandmother through the Cultural Revolution, make an unforgettable family story. The factual parts drag in places. The chapter on her mother''s time as a Party official is gripping.', 'Alex', now() - interval '476 days', now() - interval '476 days'),
('The Glass Castle', 'Jeannette Walls', 'Memoir', 4, 'Walls grew up with a father who promised the desert would be paradise and a mother who wouldn''t leave the house. It''s a brutal read, told without much self-pity. Some of the childhood scenes in Welch, West Virginia, are hard to put down.', 'Tomás', now() - interval '333 days', now() - interval '333 days'),
('Just Kids', 'Patti Smith', 'Memoir', 5, 'Patti Smith and Robert Mapplethorpe at the Chelsea Hotel in the late sixties make a love letter to New York and to art. Smith writes about her friends with real tenderness. I wanted more about the music and less about the early poetry.', 'Sam', now() - interval '71 days', now() - interval '71 days'),
('Born a Crime', 'Trevor Noah', 'Memoir', 3, 'Trevor Noah''s childhood in Soweto, where being mixed race in apartheid South Africa was a crime in itself, is funny without being glib. His mother''s stubbornness is the heart of the book. The last few chapters feel like a stand-up set.', 'Ruth', now() - interval '192 days', now() - interval '192 days'),
('H is for Hawk', 'Helen Macdonald', 'Memoir', 4, 'Helen Macdonald trains a goshawk called Mabel after losing her father, and the grief in the Suffolk woods is raw. The T.H. White sections are interesting. Sometimes the hawk stuff is a bit too much for me, but the writing is superb.', 'Priya', now() - interval '9 days', now() - interval '9 days'),
('Sapiens', 'Yuval Noah Harari', 'Non-fiction', 3, 'Harari''s sweeping account of Homo sapiens from the Cognitive Revolution onward is engaging and wide-ranging. Some of the big claims about agriculture being a trap feel overstated. Worth reading with a notepad so you can argue with it.', 'Alex', now() - interval '260 days', now() - interval '260 days'),
('Thinking, Fast and Slow', 'Daniel Kahneman', 'Non-fiction', 3, 'System 1 and System 2 give you a useful way to think about your own mistakes. Kahneman is generous about his own errors, but the book is long, and some of the studies have since been questioned. Good for dipping into.', NULL, now() - interval '410 days', now() - interval '410 days'),
('The Sixth Extinction', 'Elizabeth Kolbert', 'Non-fiction', 3, 'Kolbert travels from Panama''s frogs to the coral reefs and makes mass extinction feel urgent. The chapters are tight and well sourced. The conclusion is bleak and a bit repetitive.', 'Jordan', now() - interval '143 days', now() - interval '143 days'),
('Murder on the Orient Express', 'Agatha Christie', 'Mystery', 4, 'Poirot on a snowbound train with a murdered American and a suspicious cast of passengers is about as cosy as crime gets. The reveal is clever, even if you suspect the twist. Christie plays fair with the clues.', 'Mei', now() - interval '527 days', now() - interval '527 days'),
('The Big Sleep', 'Raymond Chandler', 'Mystery', 5, 'Philip Marlowe in Los Angeles, dealing with the Sternwood sisters and a blackmail racket, is pure atmosphere. Chandler''s similes are a joy. The plot is so tangled that I gave up on the who-did-it and just enjoyed the wisecracks.', 'Sam', now() - interval '54 days', now() - interval '54 days'),
('Gone Girl', 'Gillian Flynn', 'Thriller', 1, 'Amy''s diary entries are a clever device, but by the halfway point every character was a monster and I didn''t care what happened. Nick is insufferable in Missouri. The twist felt like a trick rather than a payoff.', 'Priya', now() - interval '6 days', now() - interval '2 days'),
('The Girl with the Dragon Tattoo', 'Stieg Larsson', 'Thriller', 2, 'Lisbeth Salander is a brilliant character stuck in a slow mystery about the Vanger family in Hedestad. The long info dumps about finance nearly killed it for me. The bleak Swedish setting works.', 'Tomás', now() - interval '205 days', now() - interval '205 days'),
('The Silent Patient', 'Alex Michaelides', 'Thriller', 3, 'The Alicia Berenson twist is clever on a first read. The therapy sessions with Theo Faber feel a bit thin. Good airport reading, but it didn''t stay with me.', 'Alex', now() - interval '22 days', now() - interval '22 days'),
('The Shining', 'Stephen King', 'Horror', 5, 'The Overlook Hotel is the most unsettling building I''ve read about, with Jack''s slow slide and those topiary animals as highlights. Danny is a great kid, and King makes the final third chaos in the best way.', 'Ruth', now() - interval '318 days', now() - interval '318 days'),
('Rosemary''s Baby', 'Ira Levin', 'Horror', 4, 'Rosemary in the Bramford, with the Castevets next door, is creepy in a slow, domestic way. Levin keeps the tension ticking over with small details like the chocolate mousse. The ending is more chilling than I expected.', 'Sam', now() - interval '97 days', now() - interval '97 days'),
('Mexican Gothic', 'Silvia Moreno-Garcia', 'Horror', 4, 'Noemí Taboada arrives at High Place to find a family rotting from the inside, and the mud and mould are gorgeously described. Moreno-Garcia riffs on Jane Eyre and Gothic tropes with confidence. The romance felt a bit rushed, and that''s my only complaint.', 'Jordan', now() - interval '40 days', now() - interval '36 days'),
('Pride and Prejudice', 'Jane Austen', 'Classics', 5, 'Elizabeth Bennet''s sharp tongue and Darcy''s slow thaw at Pemberley never get old. Austen''s social satire is still funny, especially Mr Collins. I''ve read it four times and laughed out loud every time.', 'Priya', now() - interval '489 days', now() - interval '489 days'),
('Frankenstein', 'Mary Shelley', 'Classics', 4, 'Victor''s wilful blindness and the monster''s eloquent complaints in the Alps make this more interesting than the films suggest. Walton''s frame story on the Arctic ship is slow. Shelley was around eighteen when she started it, which is hard to believe.', NULL, now() - interval '171 days', now() - interval '171 days'),
('Middlemarch', 'George Eliot', 'Classics', 3, 'Dorothea''s marriage to the dry Casaubon is painful to watch, and George Eliot''s narrator loves to lecture. Lydgate''s sections on medicine are the best part. It took me three months to finish, so it''s a commitment.', 'Mei', now() - interval '336 days', now() - interval '336 days'),
('People We Meet on Vacation', 'Emily Henry', 'Romance', 4, 'Poppy and Alex travel together every summer, and the alternating timelines do most of the heavy lifting. Their banter is great. The ending is sweet and a bit predictable, but I didn''t mind.', 'Alex', now() - interval '58 days', now() - interval '58 days'),
('Beach Read', 'Emily Henry', 'Romance', 3, 'January and Augustus swap genres over a summer in a lake town, which is a fun premise. The literary fiction side is less fun than the romance. Some of the chapters felt padded.', 'Sam', now() - interval '12 days', now() - interval '12 days'),
('The Hating Game', 'Sally Thorne', 'Romance', 4, 'Lucy and Joshua trade petty office warfare at a publishing house, and the tension is delicious. The banter is sharp. Some of the workplace stuff gets repetitive around the midpoint.', 'Tomás', now() - interval '383 days', now() - interval '383 days'),
('Circe', 'Madeline Miller', 'Fantasy', 5, 'Miller gives the witch of Aiaia her own voice, from Helios''s cold palace to Odysseus''s brief visit. The hurt and defiance are beautifully handled. I teared up near the end.', 'Ruth', now() - interval '107 days', now() - interval '102 days'),
('American Gods', 'Neil Gaiman', 'Fantasy', 4, 'Shadow gets pulled into Wednesday''s road trip across America, and Gaiman''s gods are wonderfully shabby. The Laura and Shadow scenes are a highlight. The middle section wanders, but the ending earns it.', 'Priya', now() - interval '244 days', now() - interval '244 days'),
('Station Eleven', 'Emily St. John Mandel', 'Science Fiction', 1, 'The Traveling Symphony and the Georgian flu make a neat premise, but the characters felt flat to me. Jeevan''s thread goes nowhere. For a book about the end of the world, it felt oddly passive.', 'Jordan', now() - interval '3 days', now() - interval '3 days');
